PARAMETERS [Enter Provider ID:] Long, [Enter Fiscal Year:] Long;
SELECT c.LastName & ", " & c.FirstName AS ClientName, s.ServiceName, csp.HoursPerWeek, csp.WeeklyCost
FROM tblServices AS s INNER JOIN ((tblClients AS c INNER JOIN tblClientServiceNeeds AS csn ON c.ClientID = csn.ClientID) INNER JOIN (tblProviderServiceCatalog AS psc INNER JOIN tblClientServicePlan AS csp ON psc.ProviderServiceCatalogID = csp.ProviderServiceCatalogID) ON csn.ClientServiceNeedID = csp.ClientServiceNeedID) ON s.ServiceID = csn.ServiceID
WHERE (((psc.ProviderID)=[Enter Provider ID:]) AND ((csp.FiscalYear)=[Enter Fiscal Year:]))
ORDER BY c.LastName, c.FirstName, s.ServiceName;
